const tabId = 1854033397;
const pageDetails = await browserjs(tabId, () => {
  const title = document.querySelector('h1')?.innerText;
  const price = document.querySelector('.priceView-customer-price span, .pricing-price__value, [data-testid="customer-price"]')?.innerText;
  // look for open-box links or text
  const openBoxElements = Array.from(document.querySelectorAll('a, button, div, span')).filter(el => el.innerText && el.innerText.toLowerCase().includes('open-box')).map(el => ({
    text: el.innerText.trim(),
    tagName: el.tagName,
    href: el.href || el.closest('a')?.href
  }));
  // look for carrier options (Unlocked, Verizon, AT&T, etc.)
  const carriers = Array.from(document.querySelectorAll('[data-testid*="carrier"], [aria-label*="carrier"], button, a')).filter(el => {
    const t = el.innerText?.toLowerCase() || '';
    return t.includes('unlocked') || t.includes('verizon') || t.includes('at&t') || t.includes('t-mobile');
  }).map(el => el.innerText.trim());
  return {
    title,
    price,
    openBoxElements: openBoxElements.slice(0, 10),
    carriers: carriers.slice(0, 10),
    bodySnippet: document.body.innerText.slice(0, 1000)
  };
});
