const checkOpenBoxUrls = await browserjs(tabId, async () => {
  const urls = [
    "https://www.bestbuy.com/product/samsung-galaxy-s25-256gb-silver-shadow-at-t/J3ZYG25TW9/sku/6612904/openbox",
    "https://www.bestbuy.com/product/samsung-galaxy-s25-s936u-fully-unlocked-256gb-icy-blue/JX66Z5R6ZV/sku/12930324/openbox",
    "https://www.bestbuy.com/product/samsung-galaxy-s25-256gb-unlocked-silver-shadow/J3ZYG25QZG/sku/12150786/openbox",
    "https://www.bestbuy.com/product/samsung-galaxy-s25-256gb-unlocked-navy/J3ZYG25QRV/sku/12723884/openbox"
  ];
  const results = [];
  for (const u of urls) {
    try {
      const res = await fetch(u, { method: "HEAD" });
      results.push({ url: u, status: res.status });
    } catch (e) {
      results.push({ url: u, error: e.message });
    }
  }
  return results;
});
