const tabId = 1854033397;
const searchS25Plus = await browserjs(tabId, async () => {
  // Let's use fetch on Best Buy's internal search API
  // Best Buy search API endpoint that powers the search page:
  const resp = await fetch("/site/searchpage.jsp?st=Samsung+Galaxy+S25%2B&_dyncharset=UTF-8");
  const text = await resp.text();
  const parser = new DOMParser();
  const doc = parser.parseFromString(text, "text/html");
  const items = Array.from(doc.querySelectorAll('.sku-item, li.sku-item, [data-sku-id]'));
  return {
    itemsCount: items.length,
    skus: items.map(el => {
      const h = el.querySelector('h3, h4');
      const a = el.querySelector('a[href*="/product/"], a[href*="/site/"]');
      const price = el.querySelector('.priceView-customer-price span, .pricing-price__value')?.textContent;
      return {
        sku: el.getAttribute('data-sku-id'),
        title: h?.textContent?.trim(),
        href: a?.href,
        price
      };
    })
  };
});
console.log(JSON.stringify(searchS25Plus, null, 2));

