const checkSkus = await browserjs(tabId, async () => {
  const skus = [];
  for (let s = 6612705; s <= 6612735; s++) {
    skus.push(s);
  }
  const results = [];
  for (const sku of skus) {
    try {
      const res = await fetch(`https://www.bestbuy.com/site/${sku}.p?skuId=${sku}`);
