const tabId = 1854033397;
const checkOpenBoxPages = await browserjs(tabId, async () => {
  const urls = [
    "https://www.bestbuy.com/site/6612715.p?skuId=6612715",
    "https://www.bestbuy.com/site/6612718.p?skuId=6612718",
    "https://www.bestbuy.com/site/6612722.p?skuId=6612722",
    "https://www.bestbuy.com/site/6612904.p?skuId=6612904",
    "https://www.bestbuy.com/product/samsung-galaxy-s25-128gb-unlocked-navy/J3ZYG259FS/sku/6612706/openbox?condition=excellent"
  ];
  const results = [];
  for (const u of urls) {
    const res = await fetch(u);
    const html = await res.text();
    const doc = new DOMParser().parseFromString(html, "text/html");
    const title = doc.querySelector('h1')?.textContent?.trim();
    // search for text containing "Open-Box" or "Excellent"
    const openBoxMatches = Array.from(doc.querySelectorAll('*')).filter(el => el.children.length === 0 && (el.textContent.includes('Open-Box') || el.textContent.includes('open-box'))).map(el => el.textContent.trim());
    const excellentMatches = Array.from(doc.querySelectorAll('*')).filter(el => el.children.length === 0 && el.textContent.includes('Excellent')).map(el => el.textContent.trim());
    results.push({
      url: u,
      title,
      openBoxMatches: openBoxMatches.slice(0, 5),
      excellentMatches: excellentMatches.slice(0, 5)
    });
  }
  return results;
});
console.log(JSON.stringify(checkOpenBoxPages, null, 2));

