const tabId = 1854033397;
const searchResults = await browserjs(tabId, () => {
  const allText = document.body.innerText;
  const idx = allText.indexOf('Results for');
  const relevantText = allText.slice(idx, idx + 3000);

  // Find all buttons, links, or device cards
  const devices = Array.from(document.querySelectorAll('button, a, div[class*="device"], div[class*="card"]')).map(el => ({
    text: el.innerText?.trim(),
    tagName: el.tagName,
    className: el.className
  })).filter(d => d.text && (d.text.includes('S20') || d.text.includes('Galaxy')));

  return {
    relevantText,
    devices: devices.slice(0, 15)
  };
});
console.log(JSON.stringify(searchResults, null, 2));

