const tabId = 1854033397;
const apiCheck = await browserjs(tabId, async () => {
  // Let's see how the trade-in search queries the backend
  // Look at network requests or window scripts
  const scripts = Array.from(document.querySelectorAll('script')).map(s => s.src).filter(Boolean);

  // Let's test some possible trade-in search endpoints
  const endpoints = [
    "/trade-in/api/v1/search?query=Galaxy+S20",
    "/trade-in/api/search?q=Galaxy+S20",
    "/api/trade-in/v1/devices?keyword=Galaxy+S20",
    "/trade-in/r/api/search?keyword=Galaxy+S20"
  ];
  const responses = [];
  for (const ep of endpoints) {
    try {
      const r = await fetch(ep);
      responses.push({ ep, status: r.status, text: (await r.text()).slice(0, 200) });
    } catch (e) {
      responses.push({ ep, error: e.message });
    }
  }
  return { scripts: scripts.slice(0, 10), responses };
});
console.log(JSON.stringify(apiCheck, null, 2));

