const tabId = 1854033397;
const fullTieState = await browserjs(tabId, () => {
  const state = window.__TIE_PORTAL_PRELOADED_STATE__;
  if (!state) return null;
  // Let's get structure and keys
  const getStructure = (obj, depth = 0) => {
    if (depth > 3 || obj === null || typeof obj !== 'object') return typeof obj;
    if (Array.isArray(obj)) return `Array(${obj.length}) [${typeof obj[0]}]`;
    const res = {};
    for (const k of Object.keys(obj)) {
      res[k] = getStructure(obj[k], depth + 1);
    }
    return res;
  };
  return getStructure(state);
});
console.log(JSON.stringify(fullTieState, null, 2));

