    if (match) {
      try {
        const data = JSON.parse(match[1]);
        return {
          query: mn,
          totalItems: data.appraisalPage?.searchData?.totalItems,
          firstFew: data.appraisalPage?.searchData?.products?.slice(0, 3)?.map(p => p.displayLabel)
        };
      } catch (e) {}
    }
    return { query: mn, status: r.status, len: text.length };
  }, mn);
  console.log(JSON.stringify(res));
}

