const tabId = 1854033397;
const testUrls = [
  "https://www.bestbuy.com/product/samsung-galaxy-s25-256gb-unlocked-navy/J3ZYG25QRV/sku/6612718/openbox?condition=excellent",
  "https://www.bestbuy.com/product/samsung-galaxy-s25-256gb-unlocked-silver-shadow/J3ZYG25QZG/sku/6612715/openbox?condition=excellent",
  "https://www.bestbuy.com/product/samsung-galaxy-s25-512gb-unlocked-navy/J3ZYG25Q99/sku/6612722/openbox?condition=excellent",
  "https://www.bestbuy.com/product/samsung-galaxy-s25-256gb-unlocked-navy/J3ZYG25QRV/sku/12723884/openbox?condition=excellent"
];

const res = await browserjs(tabId, async (urls) => {
  const out = [];
  for (const u of urls) {
    try {
      const r = await fetch(u);
      const text = await r.text();
      const doc = new DOMParser().parseFromString(text, "text/html");
      const title = doc.querySelector('h1')?.textContent?.trim() || doc.title;
      const price = doc.querySelector('[data-testid="customer-price"], .pricing-price__value, .priceView-customer-price span')?.textContent?.trim();
      out.push({ u, status: r.status, title, price });
    } catch (e) {
      out.push({ u, error: e.message });
    }
  }
  return out;
}, testUrls);

console.log(JSON.stringify(res, null, 2));

