const tabId = 1854033397;
const tieScript = await browserjs(tabId, async () => {
  // Let's find script that contains search or appraisal logic
  const scripts = Array.from(document.querySelectorAll('script[src]')).map(s => s.src).filter(s => s.includes('tie-portal'));
  if (scripts.length === 0) return "No tie-portal scripts on this page";

  // fetch one of them and search for api paths
  const res = await fetch(scripts[0]);
  const text = await res.text();
  const apiMatches = text.match(/https?:\/\/[^"'\s]+trade-in[^"'\s]*/g) || text.match(/\/api\/[^"'\s]*/g);
  return {
    scripts,
    apiMatches: apiMatches ? apiMatches.slice(0, 10) : []
  };
});
console.log(JSON.stringify(tieScript, null, 2));

